<?php
namespace qqworld_collector\module\collect_filter; use voku\helper\HtmlDomParser; class wipe_html_tags extends filter { public function wipe_tag(&$dom, $tag) { if ( $this->options->qc_collection_project_core == 'querylist' ) { $dom->find('div.qqworld-wipe-html-tags-wrap')->find($tag)->map(function($element) { $innerHTML = $element->html(); $element->replaceWith($innerHTML); }); if ($dom->find('div.qqworld-wipe-html-tags-wrap')->find($tag)->length()) $this->wipe_tag($dom, $tag); } else { foreach ($dom->find($tag) as $index => $element) { $text = $element->innertext; $element->outertext = $text; } $item = $dom->save(); $dom = HtmlDomParser::str_get_html($item); if (count($dom->find($tag))) $this->wipe_tag($dom, $tag); } } public function wipe($item, $selectors) { if (!empty($selectors)) { $GLOBALS['QC']->collector->engine->selector->inlucdes(); if ( $this->options->qc_collection_project_core == 'querylist' ) { $dom = $GLOBALS['QC']->collector->engine->selector->ql->html('<div class="qqworld-wipe-html-tags-wrap">' . $item . '</div>'); foreach ($selectors as $selector) $this->wipe_tag($dom, $selector); $item = $dom->find('div.qqworld-wipe-html-tags-wrap')->html(); } else { $dom = HtmlDomParser::str_get_html($item); foreach ($selectors as $selector) $this->wipe_tag($dom, $selector); $item = $dom->save(); } } return $item; } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if (!empty($args)) { $specified = isset($args['specified']) ? $args['specified'] : ''; $all = isset($args['all']) ? filter_var($args['all'], FILTER_VALIDATE_BOOLEAN) : 0; if ($all) { $item = strip_tags($item); } elseif ($specified) { $selectors = explode("\n", $specified); $selectors = array_filter($selectors, array($this, 'is_not_empty')); $item = $this->wipe($item, $selectors); } } return $item; } } ?>